import { FormEvent, useState } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

interface ProfileSettingsValues {
  name: string;
  language: string;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  onSave: (values: ProfileSettingsValues) => void;
}

export default function ProfileSettingsForm({ onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState('');
  const [language, setLanguage] = useState('ru');
  const [emailNotifications, setEmailNotifications] = useState(false);

  const handleSubmit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    onSave({ name, language, emailNotifications });
  };

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-gap, 8px)' }}>
      <JxInputField
        label="Имя"
        value={name}
        onChange={(event) => setName(event.target.value)}
      />
      <JxSelect
        label="Язык интерфейса"
        options={[
          { value: 'ru', label: 'Русский' },
          { value: 'en', label: 'English' },
        ]}
        value={language}
        onValueChange={setLanguage}
      />
      <JxSwitch
        label="Уведомления на почту"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />
      <JxButton type="submit" variant="primary">
        Сохранить
      </JxButton>
    </form>
  );
}

